<script setup>import{ref,onMounted}from'vue';import{api}from'../api';import{ShoppingBag,CircleDollarSign,Clock3,CheckCircle2}from'lucide-vue-next';const stats=ref({});async function load(){try{stats.value=await api('/api/admin/order/statistics')}catch{}}onMounted(load)</script>
<template><div class="page-head"><div><h1>Overview</h1><p>Key shop figures for today</p></div><button class="secondary" @click="load">Refresh Data</button></div><div class="metric-grid"><article><span class="metric-icon green"><ShoppingBag/></span><div><label>All Orders</label><strong>{{stats.totalCount??0}}</strong></div></article><article><span class="metric-icon amber"><Clock3/></span><div><label>Awaiting Acceptance</label><strong>{{stats.status2Count??0}}</strong></div></article><article><span class="metric-icon blue"><CheckCircle2/></span><div><label>Completed</label><strong>{{stats.status5Count??0}}</strong></div></article><article><span class="metric-icon red"><CircleDollarSign/></span><div><label>Completed Revenue</label><strong>¥ {{stats.completedAmount??0}}</strong></div></article></div><section class="plain-section"><h2>To Do</h2><div class="empty-line"><Clock3 :size="28"/><div><strong>{{stats.status2Count??0}} orders awaiting acceptance</strong><p>Go to Orders to handle new orders promptly</p></div></div></section></template>
